31		const remainingMs = Math.min(Math.max(resetMs - now, 0), windowMs);
32		const totalSeconds = Math.floor(remainingMs / 1000);
33		if (totalSeconds <= 0) return "now";
34	
35		const days = Math.floor(totalSeconds / 86_400);
36		const hours = Math.floor((totalSeconds % 86_400) / 3_600);
37		const minutes = Math.floor((totalSeconds % 3_600) / 60);
