45	 * Full reset caption: countdown plus the absolute time — clock time when the
46	 * reset lands within 24h, date otherwise. e.g. "Resets in 2h 10m · 3:22 PM",
47	 * "Resets in 5d 13h · Aug 21".
48	 */
49	export function formatResetLabel(
50		resetsAt: Date,
51		now: Date = new Date(),
52	): string {
53		const diffMs = resetsAt.getTime() - now.getTime();
